import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

@ExtendWith(MockitoExtension.class)
class ApiMapperTest {

    @Mock
    private PatientMapper patientMapper;

    @Mock
    private ProviderMapper providerMapper;

    @InjectMocks
    private ApiMapper apiMapper;

    @Test
    void shouldMapAppointmentTypeCode() {
        AppointmentType type = new AppointmentType();
        type.setTypeCode("TEL_VISIT");
        type.setDescription("Telehealth visit");
        Appointment appointment = new Appointment();
        appointment.setAppointmentType(type);

        AppointmentResponse response = apiMapper.toResponse(appointment);

        Assertions.assertEquals("TEL_VISIT", response.getAppointmentType());
    }

    @Test
    void shouldLeaveAppointmentTypeNullWhenMissing() {
        Appointment appointment = new Appointment();

        AppointmentResponse response = apiMapper.toResponse(appointment);

        Assertions.assertNull(response.getAppointmentType());
    }
}

package com.clinictraining.medbackend.graphql;

import graphql.language.FieldDefinition;
import graphql.language.ObjectTypeDefinition;
import graphql.language.TypeName;
import graphql.schema.idl.SchemaParser;
import graphql.schema.idl.TypeDefinitionRegistry;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;

class GraphQlSchemaTest {

    @Test
    void shouldExposeNullableAppointmentTypeOnAppointment() throws IOException {
        ObjectTypeDefinition appointment = loadSchema()
                .getType("Appointment", ObjectTypeDefinition.class)
                .orElseThrow();

        FieldDefinition field = appointment.getFieldDefinitions().stream()
                .filter(definition -> "appointmentType".equals(definition.getName()))
                .findFirst()
                .orElseThrow(() -> new AssertionError("Appointment.appointmentType is missing"));

        // Nullable on purpose: legacy rows may lack a type and existing clients must keep working.
        Assertions.assertInstanceOf(TypeName.class, field.getType());
        Assertions.assertEquals("String", ((TypeName) field.getType()).getName());
    }

    private TypeDefinitionRegistry loadSchema() throws IOException {
        try (InputStream stream = getClass().getResourceAsStream("/graphql/schema.graphqls")) {
            Assertions.assertNotNull(stream, "schema.graphqls not found on classpath");
            return new SchemaParser().parse(new InputStreamReader(stream, StandardCharsets.UTF_8));
        }
    }
}

